package dev.mesbase;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;
import dev.mesbase.platform.management.*;import dev.mesbase.platform.management.PlatformContracts.*;
import dev.mesbase.infrastructure.platform.PlatformRows.*;import dev.mesbase.infrastructure.platform.*;
import dev.mesbase.infrastructure.persistence.*;import dev.mesbase.infrastructure.catalog.*;
import dev.mesbase.core.factory.*;import dev.mesbase.core.error.*;import dev.mesbase.platform.execution.FactoryContext;
/** TEST ONLY real Platform SQL + Quartz, isolated H2 schema, no production account/config/data. */
class PlatformServiceTest {
 @TempDir Path temp;com.zaxxer.hikari.HikariDataSource pool;PlatformStore store;PlatformService platform;FactoryCatalog catalog;
 final org.springframework.security.crypto.password.PasswordEncoder encoder=org.springframework.security.crypto.factory.PasswordEncoderFactories.createDelegatingPasswordEncoder();
 static final String PASSWORD="TEST-ONLY-password-12345";
 @BeforeEach void setup(){pool=RuntimeFixture.pool("platform");org.flywaydb.core.Flyway.configure().dataSource(pool).locations("classpath:db/platform").load().migrate();store=new PlatformStore(new PlatformPersistence(pool,Set.of(PlatformMapper.class)));catalog=new InMemoryFactoryCatalog(List.of(new Factory(new FactoryId("A"),"TEST","A","TEST ONLY A",FactoryStatus.ENABLED),new Factory(new FactoryId("B"),"TEST","B","TEST ONLY B",FactoryStatus.ENABLED)));platform=new PlatformService(store,catalog,encoder);}
 @AfterEach void close(){FactoryContext.clear();pool.close();}
 UserView user(String name,Status status){return platform.createUser(new NewUser(new UserInput(name,"TEST ONLY "+name,status),new PasswordInput(PASSWORD)));}
 @Test void usersPasswordAndDisabledStatus(){var u=user("visitor",Status.ENABLED);assertNotNull(platform.me("visitor"));assertFalse(u.toString().contains("password"));assertTrue(store.run(m->m.findUser(u.id()).passwordHash()).startsWith("{bcrypt}"));var clock=Clock.fixed(Instant.parse("2026-10-05T00:00:00Z"),ZoneOffset.UTC);var sessions=new SessionService(store,encoder,clock,Duration.ofHours(1));var token=sessions.login(new Login("visitor",PASSWORD),UUID.randomUUID().toString());assertEquals("visitor",sessions.authenticate(token.accessToken()));platform.password(u.id(),new PasswordInput("TEST-ONLY-new-password-999"));assertThrows(FoundationException.class,()->sessions.authenticate(token.accessToken()));assertThrows(FoundationException.class,()->sessions.login(new Login("visitor",PASSWORD),UUID.randomUUID().toString()));platform.updateUser(u.id(),new UserInput("visitor","TEST ONLY",Status.DISABLED));assertThrows(FoundationException.class,()->sessions.login(new Login("visitor","TEST-ONLY-new-password-999"),UUID.randomUUID().toString()));}
 @Test void loginWrongDisabledNoRoleLogoutAndExpiry(){var u=user("empty-role",Status.ENABLED);user("disabled",Status.DISABLED);var base=Instant.parse("2026-10-05T00:00:00Z");var current=new java.util.concurrent.atomic.AtomicReference<>(base);Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return current.get();}};var sessions=new SessionService(store,encoder,clock,Duration.ofSeconds(10));assertThrows(FoundationException.class,()->sessions.login(new Login("empty-role","wrong-password"),UUID.randomUUID().toString()));assertThrows(FoundationException.class,()->sessions.login(new Login("disabled",PASSWORD),UUID.randomUUID().toString()));var token=sessions.login(new Login("empty-role",PASSWORD),UUID.randomUUID().toString());assertEquals("empty-role",sessions.authenticate(token.accessToken()));assertFalse(platform.granted("empty-role","A","foundation:access:read"));assertFalse(platform.granted("empty-role",null,"platform:users:read"));sessions.logout(token.accessToken());assertThrows(FoundationException.class,()->sessions.authenticate(token.accessToken()));var expired=sessions.login(new Login("empty-role",PASSWORD),UUID.randomUUID().toString());current.set(base.plusSeconds(11));assertThrows(FoundationException.class,()->sessions.authenticate(expired.accessToken()));assertFalse(store.run(m->m.listSession(0,100)).toString().contains(expired.accessToken()));assertEquals(4,platform.logins(0,100).size());}
 @Test void factoryRolesAndPlatformRoleNeverImplyEachOther(){var u=user("operator",Status.ENABLED);var a=platform.saveRole(null,new RoleInput("A reader",RoleKind.FACTORY,"A",Status.ENABLED));var b=platform.saveRole(null,new RoleInput("B reader",RoleKind.FACTORY,"B",Status.ENABLED));var admin=platform.saveRole(null,new RoleInput("Platform",RoleKind.PLATFORM,null,Status.ENABLED));var menu=platform.saveMenu(null,new MenuInput(null,"查看","/foundation","foundation:access:read",1,MenuKind.MENU));var pm=platform.saveMenu(null,new MenuInput(null,"账号","/platform/users","platform:users:read",2,MenuKind.MENU));platform.roleMenus(a.id(),new Links(List.of(menu.id())));platform.roleMenus(admin.id(),new Links(List.of(pm.id())));platform.userRoles(u.id(),new Links(List.of(a.id(),b.id())));assertTrue(platform.granted("operator","A","foundation:access:read"));assertFalse(platform.granted("operator","B","foundation:access:read"));assertFalse(platform.granted("operator",null,"platform:users:read"));assertEquals(1,platform.navigation("operator","A").menus().size());assertEquals(0,platform.navigation("operator","B").menus().size());platform.userRoles(u.id(),new Links(List.of(admin.id())));assertTrue(platform.granted("operator",null,"platform:users:read"));assertFalse(platform.granted("operator","A","platform:users:read"));assertThrows(FoundationException.class,()->platform.saveRole(null,new RoleInput("invalid",RoleKind.PLATFORM,"0",Status.ENABLED)));}
 @Test void batchLinksRollbackWhenReferencedResourceMissing(){var u=user("operator",Status.ENABLED);var r=platform.saveRole(null,new RoleInput("A",RoleKind.FACTORY,"A",Status.ENABLED));platform.userRoles(u.id(),new Links(List.of(r.id())));assertThrows(FoundationException.class,()->platform.userRoles(u.id(),new Links(List.of("missing"))));assertEquals(1,store.run(m->m.roles(u.id())).size());}
 @Test void menuTreeAndCycleRejected(){var root=platform.saveMenu(null,new MenuInput(null,"目录","/platform","platform:menus:read",0,MenuKind.MENU));var child=platform.saveMenu(null,new MenuInput(root.id(),"菜单","/platform/menus","platform:menus:write",1,MenuKind.MENU));assertThrows(FoundationException.class,()->platform.saveMenu(root.id(),new MenuInput(child.id(),"循环","/platform","platform:menus:read",0,MenuKind.MENU)));}
 @Test void dictCrudCacheInvalidationAndUnique(){var type=platform.saveType(null,new DictTypeInput("test_only_status","TEST ONLY 状态"));var value=platform.saveData(null,new DictDataInput(type.id(),"1","已启用",0));assertEquals("已启用",platform.dictionary(type.code()).getFirst().label());platform.saveData(value.id(),new DictDataInput(type.id(),"1","启用",0));assertEquals("启用",platform.dictionary(type.code()).getFirst().label());assertThrows(FoundationException.class,()->platform.saveData(null,new DictDataInput(type.id(),"1","重复",0)));platform.deleteData(value.id());assertTrue(platform.dictionary(type.code()).isEmpty());platform.deleteType(type.id());assertThrows(FoundationException.class,()->platform.dictionary(type.code()));}
 @Test void configGlobalFactoryAndInvalidationNoSecret(){var g=platform.saveConfig(null,new ConfigInput("test.mode","global",ConfigKind.GLOBAL,null));var a=platform.saveConfig(null,new ConfigInput("test.mode","A-value",ConfigKind.FACTORY,"A"));platform.saveConfig(null,new ConfigInput("test.mode","B-value",ConfigKind.FACTORY,"B"));assertEquals("global",platform.config(null,"test.mode").orElseThrow().configValue());assertEquals("A-value",platform.config("A","test.mode").orElseThrow().configValue());assertEquals("B-value",platform.config("B","test.mode").orElseThrow().configValue());assertTrue(platform.config("A","missing").isEmpty());platform.saveConfig(a.id(),new ConfigInput("test.mode","A-updated",ConfigKind.FACTORY,"A"));assertEquals("A-updated",platform.config("A","test.mode").orElseThrow().configValue());assertThrows(FoundationException.class,()->platform.saveConfig(null,new ConfigInput("api.secret","must-reject",ConfigKind.GLOBAL,null)));platform.deleteConfig(g.id());assertTrue(platform.config(null,"test.mode").isEmpty());}
 @Test void privateFilesRequireOwnerFactoryResourceAndSizeLimit()throws Exception{var u=user("owner",Status.ENABLED);var other=user("other",Status.ENABLED);var files=new FileService(store,temp.toRealPath().resolve("files"),10);var a=new FactoryScope(new FactoryId("A"));var b=new FactoryScope(new FactoryId("B"));var f=files.upload(u.id(),a,"personal","../TEST-ONLY.txt",new java.io.ByteArrayInputStream("hello".getBytes()));assertEquals("TEST-ONLY.txt",f.originalName());assertEquals("hello",new String(files.download(f.id(),u.id(),a,"personal")));assertThrows(FoundationException.class,()->files.download(f.id(),other.id(),a,"personal"));assertThrows(FoundationException.class,()->files.download(f.id(),u.id(),b,"personal"));assertThrows(FoundationException.class,()->files.download(f.id(),u.id(),null,"personal"));assertThrows(FoundationException.class,()->files.download(f.id(),u.id(),a,"foreign"));assertThrows(FoundationException.class,()->files.upload(u.id(),a,"personal","oversize",new java.io.ByteArrayInputStream(new byte[11])));try(var paths=Files.list(temp.toRealPath().resolve("files"))){assertEquals(1,paths.count());}}
 @Test void quartzPlatformFactoryMissingScopeAllowlistAndLogs()throws Exception{var auditActor=user("test-operator-"+"x".repeat(40),Status.ENABLED);var scopes=new ArrayList<String>();try(var jobs=new JobService(store,catalog,Map.of("platform-test",new JobService.RegisteredHandler(JobScope.PLATFORM,()->scopes.add(FactoryContext.current().isEmpty()?"PLATFORM":"BAD")),"factory-test",new JobService.RegisteredHandler(JobScope.FACTORY,()->scopes.add(FactoryContext.required().factoryId().value()))))){jobs.start();var p=jobs.save(null,new JobInput("TEST ONLY platform","platform-test",JobScope.PLATFORM,null,"0 0 0 1 1 ? 2099",Status.ENABLED));var a=jobs.save(null,new JobInput("TEST ONLY factory","factory-test",JobScope.FACTORY,"A","0 0 0 1 1 ? 2099",Status.ENABLED));assertThrows(FoundationException.class,()->jobs.save(null,new JobInput("bad","factory-test",JobScope.FACTORY,null,"0 * * * * ?",Status.ENABLED)));assertThrows(FoundationException.class,()->jobs.save(null,new JobInput("reflective","bean.method()",JobScope.PLATFORM,null,"0 * * * * ?",Status.ENABLED)));FactoryContext.bind(new FactoryScope(new FactoryId("B")));jobs.runForActor(p.id(),auditActor.username(),UUID.randomUUID().toString());jobs.runForActor(a.id(),auditActor.username(),UUID.randomUUID().toString());assertEquals(List.of("PLATFORM","A"),scopes);assertEquals("B",FactoryContext.required().factoryId().value());var logs=platform.jobLogs(0,100);assertEquals(2,logs.size());assertTrue(logs.stream().allMatch(l->l.actorId().equals(auditActor.id())));assertTrue(logs.stream().anyMatch(l->l.executionScope()==JobScope.FACTORY&&l.factoryId().equals("A")));var disabled=jobs.save(p.id(),new JobInput("disabled","platform-test",JobScope.PLATFORM,null,p.cron(),Status.DISABLED));assertThrows(FoundationException.class,()->jobs.run(disabled.id(),"TEST",UUID.randomUUID().toString()));jobs.delete(disabled.id());}}
 @Test void quartzClaimIsSharedBetweenManualAndSchedulerAndTokenSafe()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);try(var jobs=new JobService(store,catalog,Map.of("hold",new JobService.RegisteredHandler(JobScope.PLATFORM,()->{entered.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}})))){var j=jobs.save(null,new JobInput("TEST ONLY claim","hold",JobScope.PLATFORM,null,"0 0 0 1 1 ? 2099",Status.ENABLED));try(var executor=Executors.newSingleThreadExecutor()){var first=executor.submit(()->jobs.run(j.id(),"TEST",UUID.randomUUID().toString()));assertTrue(entered.await(5,TimeUnit.SECONDS));assertThrows(FoundationException.class,()->jobs.run(j.id(),"TEST",UUID.randomUUID().toString()));assertEquals(0,store.run(m->m.releaseJob(j.id(),"wrong-token")).intValue());release.countDown();first.get(5,TimeUnit.SECONDS);}assertFalse(jobs.list(0,100).getFirst().running());}}

 @Test void initialAdminIsExplicitHasNoMagicIdAndCannotProvisionOverExistingUsers(){var bootstrap=new PlatformBootstrap(store,encoder);String adminId=bootstrap.provision("test-admin",PASSWORD);assertNotEquals("1",adminId);assertTrue(platform.granted("test-admin",null,"platform:users:write"));assertFalse(platform.granted("test-admin","A","platform:users:write"));assertThrows(FoundationException.class,()->bootstrap.provision("other-admin",PASSWORD));assertEquals(1,platform.users(0,100).size());}
 @Test void cacheVersionInvalidatesAnotherServiceInstance(){var other=new PlatformService(store,catalog,encoder);var type=platform.saveType(null,new DictTypeInput("test_cache","TEST ONLY"));var data=platform.saveData(null,new DictDataInput(type.id(),"1","old",1));assertEquals("old",other.dictionary(type.code()).getFirst().label());platform.saveData(data.id(),new DictDataInput(type.id(),"1","new",1));assertEquals("new",other.dictionary(type.code()).getFirst().label());var config=platform.saveConfig(null,new ConfigInput("test.key","old",ConfigKind.GLOBAL,null));assertEquals("old",other.config(null,"test.key").orElseThrow().configValue());platform.saveConfig(config.id(),new ConfigInput("test.key","new",ConfigKind.GLOBAL,null));assertEquals("new",other.config(null,"test.key").orElseThrow().configValue());}
 @Test void throwingRegisteredTaskHasUnknownOutcomeAndReleasesClaim()throws Exception{try(var jobs=new JobService(store,catalog,Map.of("fail",new JobService.RegisteredHandler(JobScope.PLATFORM,()->{throw new IllegalStateException("TEST ONLY original cause");})))){var job=jobs.save(null,new JobInput("TEST ONLY unknown","fail",JobScope.PLATFORM,null,"0 0 0 1 1 ? 2099",Status.ENABLED));assertThrows(IllegalStateException.class,()->jobs.run(job.id(),"TEST",UUID.randomUUID().toString()));assertFalse(jobs.list(0,100).getFirst().running());assertEquals("UNKNOWN",platform.jobLogs(0,100).getFirst().outcome());}}
}
